(function(){
  const feathers = [];
  const N = 70;
  for(let i=0;i<N;i++){
    feathers.push({
      x: Math.random()*W(),
      y: Math.random()*H()*1.5 + H()*0.3,
      size: 2+Math.random()*4,
      speed: 0.15+Math.random()*0.35,
      drift: Math.random()*Math.PI*2,
      driftSpeed: 0.002+Math.random()*0.004,
      opacity: 0.15+Math.random()*0.35,
      trail: []
    });
  }

  let t = 0;

  function drawDove(cx, cy, scale, wingAngle, color){
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(scale, scale);
    ctx.rotate(-0.15);

    ctx.beginPath();
    ctx.moveTo(-40, 0);
    ctx.bezierCurveTo(-30,-18, 10,-20, 45,-4);
    ctx.bezierCurveTo(55,-2,60,2,50,4);
    ctx.bezierCurveTo(20,10,-20,14,-40,4);
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.85;
    ctx.fill();

    ctx.beginPath();
    ctx.ellipse(48,-2,9,7,0,0,Math.PI*2);
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(56,-2);
    ctx.lineTo(64,0);
    ctx.lineTo(56,2);
    ctx.closePath();
    ctx.fill();

    ctx.save();
    ctx.translate(-5,-6);
    ctx.rotate(wingAngle);
    ctx.beginPath();
    ctx.moveTo(0,0);
    ctx.bezierCurveTo(-10,-30,-45,-40,-70,-25);
    ctx.bezierCurveTo(-50,-15,-30,-5,0,10);
    ctx.closePath();
    ctx.globalAlpha = 0.75;
    ctx.fill();
    ctx.restore();

    ctx.beginPath();
    ctx.moveTo(-40,2);
    ctx.bezierCurveTo(-60,0,-75,6,-85,14);
    ctx.bezierCurveTo(-70,10,-55,10,-40,8);
    ctx.closePath();
    ctx.globalAlpha = 0.7;
    ctx.fill();

    ctx.restore();
    ctx.globalAlpha = 1;
  }

  function frame(){
    ctx.clearRect(0,0,W(),H());
    t += 0.016;
    const w = W(), h = H();

    const gx = w*0.74, gy = h*0.24;
    const grad = ctx.createRadialGradient(gx,gy,0,gx,gy, Math.max(w,h)*0.4);
    grad.addColorStop(0, PALETTE[0] + 'aa');
    grad.addColorStop(1, PALETTE[0] + '00');
    ctx.save();
    ctx.globalAlpha = DARK ? 0.25 : 0.35;
    ctx.fillStyle = grad;
    ctx.fillRect(0,0,w,h);
    ctx.restore();

    for(let r=0;r<3;r++){
      const phase = t*0.15 + r*2.1;
      const radius = 40 + (phase % 6) * 30;
      const alpha = Math.max(0, 0.18 - (radius/300));
      if(alpha<=0) continue;
      ctx.beginPath();
      ctx.strokeStyle = PALETTE[1];
      ctx.globalAlpha = alpha;
      ctx.lineWidth = 1.2;
      ctx.arc(gx, gy+10, radius, 0, Math.PI*2);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    for(const f of feathers){
      f.trail.push({x:f.x, y:f.y});
      if(f.trail.length>6) f.trail.shift();

      f.drift += f.driftSpeed;
      f.x += Math.sin(f.drift)*0.4 + 0.25;
      f.y -= f.speed;

      if(f.y < -20){
        f.y = h + 20;
        f.x = Math.random()*w;
      }
      if(f.x > w+20) f.x = -20;

      for(let i=0;i<f.trail.length;i++){
        const p = f.trail[i];
        const a = (i/f.trail.length) * f.opacity * 0.6;
        ctx.beginPath();
        ctx.fillStyle = PALETTE[2];
        ctx.globalAlpha = a;
        ctx.ellipse(p.x, p.y, f.size*0.6, f.size*1.1, Math.sin(f.drift)*0.5, 0, Math.PI*2);
        ctx.fill();
      }

      ctx.beginPath();
      ctx.fillStyle = PALETTE[1];
      ctx.globalAlpha = f.opacity;
      ctx.ellipse(f.x, f.y, f.size*0.7, f.size*1.3, Math.sin(f.drift)*0.6, 0, Math.PI*2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    const flightT = (t*0.06) % 1;
    const dx = w*0.15 + flightT*w*0.7;
    let dy = h*0.22 + Math.sin(flightT*Math.PI*2)*h*0.03;
    if (Math.abs(dx - w/2) < w*0.22) {
      dy = h*0.13;
    }
    const wingAngle = Math.sin(t*3.2)*0.5 - 0.15;
    const scale = Math.min(w,h)/1000 * 1.1;

    drawDove(dx, dy, scale, wingAngle, PALETTE[2]);

    requestAnimationFrame(frame);
  }

  requestAnimationFrame(frame);
})();
